css:
:scope { width: min(100%, 714px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 24; grid-row: 1 / span 3; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 700; line-height: 1.55; letter-spacing: 0.22em; text-transform: uppercase; text-align: center; color: var(--os-color-link); }
.gx__i2 { grid-column: 1 / span 24; grid-row: 5 / span 34; font-family: var(--os-font-heading); font-size: 93.7px; font-weight: 700; line-height: 0.95; letter-spacing: -0.025em; text-align: center; color: var(--os-color-heading); }
.gx__i3 { grid-column: 6 / span 12; grid-row: 44 / span 8; font-family: var(--os-font-label); font-size: 14.9px; font-weight: 700; line-height: 1.43; letter-spacing: 0.2em; text-transform: uppercase; text-align: center; color: var(--os-color-background); }
.gx__i3 { justify-self: center; }
.gx__i4 { grid-column: 1 / span 24; grid-row: 56 / span 5; font-family: var(--os-font-label); font-size: 13.7px; font-weight: 400; line-height: 1.4; letter-spacing: 0.16em; text-transform: uppercase; text-align: center; color: var(--os-color-text); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 75px; }
  .gx__i3 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i4 { font-family: var(--os-font-label); font-size: 14px; }
}
